insert into passages (id, text, difficulty_level, b, active) values
('77750541-cbd8-4d74-a746-76e62e03b263', 'Many cities around the world are experimenting with car-free zones in their downtown areas, closing certain streets to vehicle traffic and reserving them for pedestrians, cyclists, and public transportation. Supporters argue that these zones reduce air pollution, encourage physical activity, and make city centers more pleasant places to spend time. Local businesses in car-free zones sometimes report increased foot traffic, since people are more likely to browse shops when they are not rushing past in cars. However, some business owners worry that limiting car access could reduce sales, particularly for stores that rely on customers who prefer to drive and park nearby. City planners generally respond to these concerns by adding convenient parking areas just outside the car-free zone and improving public transportation connections, so that visitors can still reach the area easily without needing to drive directly into it.', 2, -1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('8085d9cf-ae7d-440c-93f3-18ce083e5f09', 'sentence_completion', 'The company decided to ___ the broken equipment instead of repairing it again.', NULL, '[{"id": "b", "text": "replace"}, {"id": "c", "text": "fix"}, {"id": "a", "text": "clean"}, {"id": "d", "text": "paint"}]'::jsonb, 0, '{"strategy": "instead of repairing it again = במקום לתקן שוב. מה עושים כשתיקון חוזר לא משתלם?", "correct_reason": "replace = להחליף. חלופה לתיקון חוזר היא החלפה.", "options_analysis": ["נכון! replace = להחליף — אלטרנטיבה לתיקון חוזר", "fix = לתקן — סותר ''instead of repairing''", "clean = לנקות — לא פותר תקלה", "paint = לצבוע — לא רלוונטי לציוד שבור"]}', 1.45, -1.0, 0.25, 2, 'ai', NULL, true),
('8f003f9e-ae49-4f93-8a87-14af3037236d', 'sentence_completion', 'She was ___ to hear that the flight had been delayed again.', NULL, '[{"id": "c", "text": "thrilled"}, {"id": "b", "text": "frustrated"}, {"id": "d", "text": "proud"}, {"id": "a", "text": "calm"}]'::jsonb, 1, '{"strategy": "delayed again = התעכבה שוב. איך מרגישים כשמעכבים טיסה שוב?", "correct_reason": "frustrated = מתוסכלת. עיכוב חוזר מתסכל.", "options_analysis": ["thrilled = נרגשת — הפוך מתגובה לעיכוב", "נכון! frustrated = מתוסכלת — תגובה טבעית לעיכוב חוזר", "proud = גאה — לא קשור לעיכוב", "calm = רגועה — פחות סביר לעיכוב חוזר"]}', 1.13, -1.0, 0.25, 2, 'ai', NULL, true),
('23473d1d-e640-4f8d-a22f-7c2d85a4669b', 'sentence_completion', 'The manager asked the team to ___ their reports before the deadline.', NULL, '[{"id": "c", "text": "hide"}, {"id": "b", "text": "ignore"}, {"id": "a", "text": "submit"}, {"id": "d", "text": "forget"}]'::jsonb, 2, '{"strategy": "before the deadline = לפני המועד האחרון. מה עושים עם דוחות לפני דדליין?", "correct_reason": "submit = להגיש. דוחות מוגשים לפני מועד אחרון.", "options_analysis": ["hide = להסתיר — לא רלוונטי לדוחות עבודה", "ignore = להתעלם מ- — לא רלוונטי לדוחות", "נכון! submit = להגיש — פעולה נדרשת לפני דדליין", "forget = לשכוח — לא רלוונטי לדדליין"]}', 1.32, -1.0, 0.25, 2, 'ai', NULL, true),
('5d5f581c-6163-4296-a879-4f688a9f4c97', 'sentence_completion', 'The doctor recommended that he ___ more water throughout the day.', NULL, '[{"id": "b", "text": "sell"}, {"id": "c", "text": "avoid"}, {"id": "d", "text": "spill"}, {"id": "a", "text": "drink"}]'::jsonb, 3, '{"strategy": "recommended...throughout the day = המליץ...לאורך היום. מה ממליץ רופא לגבי מים?", "correct_reason": "drink = לשתות. רופא ממליץ לשתות מים.", "options_analysis": ["sell = למכור — לא רלוונטי בכלל", "avoid = להימנע מ- — הפוך מהמלצה בריאותית", "spill = לשפוך — לא רלוונטי להמלצה", "נכון! drink = לשתות — המלצה רפואית נפוצה"]}', 1.14, -1.0, 0.25, 2, 'ai', NULL, true),
('b30a73a5-4197-46e6-9e28-b53cfeabd428', 'sentence_completion', 'The children were told to ___ quiet during the movie.', NULL, '[{"id": "b", "text": "stay"}, {"id": "a", "text": "run"}, {"id": "c", "text": "leave"}, {"id": "d", "text": "shout"}]'::jsonb, 0, '{"strategy": "during the movie = במהלך הסרט. מה מבקשים מילדים בקולנוע?", "correct_reason": "stay = להישאר. מבקשים מהם להישאר שקטים.", "options_analysis": ["נכון! stay = להישאר — מתאים לבקשה להישאר שקטים", "run = לרוץ — לא רלוונטי לישיבה בקולנוע", "leave = לעזוב — סותר את ההקשר של להישאר בסרט", "shout = לצעוק — הפוך מ''quiet''"]}', 1.22, -1.0, 0.25, 2, 'ai', NULL, true),
('6ac61eb8-2b67-4132-acba-4df3841f7b13', 'sentence_completion', 'The company''s sales ___ dramatically after the holiday season ended.', NULL, '[{"id": "c", "text": "increased"}, {"id": "b", "text": "dropped"}, {"id": "d", "text": "celebrated"}, {"id": "a", "text": "remained"}]'::jsonb, 1, '{"strategy": "after the holiday season ended = אחרי סוף עונת החגים. מה קורה למכירות אחרי חגים?", "correct_reason": "dropped = ירדו. מכירות בד''כ יורדות אחרי החגים.", "options_analysis": ["increased = עלו — פחות סביר אחרי סוף עונת חגים", "נכון! dropped = ירדו — דפוס נפוץ אחרי החגים", "celebrated = חגגו — לא רלוונטי למכירות", "remained = נשארו — פחות סביר, ''dramatically'' מרמז על שינוי"]}', 0.91, -1.0, 0.25, 2, 'ai', NULL, true),
('67cd6eca-5690-402d-842d-8020c60afb97', 'sentence_completion', 'The volunteers worked hard to ___ the park before the festival.', NULL, '[{"id": "a", "text": "dirty"}, {"id": "d", "text": "sell"}, {"id": "c", "text": "clean"}, {"id": "b", "text": "ignore"}]'::jsonb, 2, '{"strategy": "before the festival = לפני הפסטיבל. מה עושים מתנדבים לפארק לפני אירוע?", "correct_reason": "clean = לנקות. מתנדבים מנקים לפני אירוע.", "options_analysis": ["dirty = ללכלך — הפוך ממאמץ מתנדבים", "sell = למכור — לא רלוונטי לפארק", "נכון! clean = לנקות — פעולה טבעית לפני אירוע ציבורי", "ignore = להתעלם מ- — סותר ''worked hard''"]}', 0.92, -1.0, 0.25, 2, 'ai', NULL, true),
('a84c2d32-d443-420a-9fde-1fcd302f477c', 'sentence_completion', 'The teacher tried to ___ the difficult concept using simple examples.', NULL, '[{"id": "c", "text": "copy"}, {"id": "d", "text": "hide"}, {"id": "a", "text": "forget"}, {"id": "b", "text": "explain"}]'::jsonb, 3, '{"strategy": "using simple examples = בעזרת דוגמאות פשוטות. מה עושה מורה עם רעיון קשה?", "correct_reason": "explain = להסביר. מורה מסבירה רעיונות קשים עם דוגמאות.", "options_analysis": ["copy = להעתיק — לא מתאר הוראה", "hide = להסתיר — הפוך ממטרת הוראה", "forget = לשכוח — לא רלוונטי להוראה", "נכון! explain = להסביר — מתאים לשימוש בדוגמאות"]}', 0.96, -1.0, 0.25, 2, 'ai', NULL, true),
('f9054da2-7ee1-4975-9a12-37fe9c954b61', 'sentence_completion', 'The new employee felt ___ during her first week at the company.', NULL, '[{"id": "d", "text": "nervous"}, {"id": "b", "text": "bored"}, {"id": "a", "text": "confident"}, {"id": "c", "text": "angry"}]'::jsonb, 0, '{"strategy": "first week = שבוע ראשון. איך מרגישים בשבוע ראשון בעבודה חדשה?", "correct_reason": "nervous = לחוצה. שבוע ראשון בד''כ מלחיץ.", "options_analysis": ["נכון! nervous = לחוצה — תגובה נפוצה לשבוע ראשון", "bored = משועממת — פחות סביר בשבוע ראשון עמוס", "confident = בטוחה בעצמה — פחות סביר בשבוע ראשון", "angry = כועסת — לא קשור לשבוע ראשון"]}', 1.12, -1.0, 0.25, 2, 'ai', NULL, true),
('15a2d26c-ce59-4ce8-8500-9523a6725a96', 'sentence_completion', 'The airline ___ passengers for the delay by offering free meals.', NULL, '[{"id": "a", "text": "ignored"}, {"id": "c", "text": "compensated"}, {"id": "d", "text": "blamed"}, {"id": "b", "text": "confused"}]'::jsonb, 1, '{"strategy": "offering free meals = הציעה ארוחות חינם. למה חברת תעופה מציעה זאת?", "correct_reason": "compensated = פיצתה. ארוחות חינם הן פיצוי על עיכוב.", "options_analysis": ["ignored = התעלמה מ- — סותר את מתן הארוחות", "נכון! compensated = פיצתה — ארוחות חינם הן צורת פיצוי", "blamed = האשימה — הפוך מפיצוי", "confused = בלבלה — לא רלוונטי"]}', 1.59, -1.0, 0.25, 2, 'ai', NULL, true),
('7511b310-acf0-4c0b-8293-7d5f17477d80', 'sentence_completion', 'The article ___ readers about the dangers of texting while driving.', NULL, '[{"id": "d", "text": "celebrates"}, {"id": "a", "text": "hides"}, {"id": "c", "text": "warns"}, {"id": "b", "text": "forgets"}]'::jsonb, 2, '{"strategy": "dangers of texting while driving = סכנות ההודעות תוך כדי נהיגה. מה עושה כתבה עם סכנות?", "correct_reason": "warns = מזהירה. כתבה על סכנות מזהירה את הקוראים.", "options_analysis": ["celebrates = חוגגת — לא רלוונטי לסכנות", "hides = מסתירה — הפוך ממטרת אזהרה", "נכון! warns = מזהירה — פעולה טבעית של כתבה על סכנות", "forgets = שוכחת — לא רלוונטי לכתבה"]}', 1.38, -1.0, 0.25, 2, 'ai', NULL, true),
('2fd348c0-3b11-4db6-aef0-1d09b1c4f9d8', 'sentence_completion', 'The city plans to ___ a new library in the downtown area.', NULL, '[{"id": "b", "text": "ignore"}, {"id": "a", "text": "destroy"}, {"id": "d", "text": "sell"}, {"id": "c", "text": "build"}]'::jsonb, 3, '{"strategy": "new library = ספרייה חדשה. מה עושה עיר עם ''new library''?", "correct_reason": "build = לבנות. עיר בונה ספרייה חדשה.", "options_analysis": ["ignore = להתעלם מ- — סותר תוכניות עתידיות", "destroy = להרוס — סותר ''new''", "sell = למכור — לא רלוונטי לספרייה ציבורית", "נכון! build = לבנות — פעולה טבעית ל''new library''"]}', 0.94, -1.0, 0.25, 2, 'ai', NULL, true),
('81efe01d-300b-4264-8afd-12f4d3334761', 'restatement', 'Although he was nervous, he gave an excellent presentation.', NULL, '[{"id": "d", "text": "Even though he was nervous, his presentation was excellent."}, {"id": "a", "text": "He gave a poor presentation because he was nervous."}, {"id": "b", "text": "His presentation was excellent, which made him nervous."}, {"id": "c", "text": "He was not nervous during his presentation."}]'::jsonb, 0, '{"strategy": "although nervous, excellent = למרות עצבנות, מצוינת. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["נכון! אותה משמעות בדיוק: מצוינת למרות העצבנות", "סותר ''excellent presentation''", "הופך סיבה ותוצאה", "סותר ''he was nervous'' במקור"]}', 1.13, -1.0, 0.25, 2, 'ai', NULL, true),
('08307e4c-538f-486e-8c37-bdff697e98c1', 'restatement', 'The company launched the product early because demand was so high.', NULL, '[{"id": "c", "text": "The company launched the product late due to low demand."}, {"id": "d", "text": "Because demand was so high, the company launched the product early."}, {"id": "b", "text": "The high demand was caused by the early launch."}, {"id": "a", "text": "Demand was low, so the company delayed the launch."}]'::jsonb, 1, '{"strategy": "launched early because high demand = השיקה מוקדם בגלל ביקוש. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הפוך — ''late'' ו''low demand'' סותרים את המקור", "נכון! אותה סיבה-תוצאה בדיוק", "הופך סיבה ותוצאה", "סותר ''demand was so high''"]}', 1.3, -1.0, 0.25, 2, 'ai', NULL, true),
('cc5c17f4-719d-494c-b99f-951d3fa3bafa', 'restatement', 'She canceled her trip because of the sudden storm warning.', NULL, '[{"id": "c", "text": "The storm warning was issued after she canceled her trip."}, {"id": "b", "text": "There was no storm warning at all."}, {"id": "d", "text": "She canceled her trip due to the sudden storm warning."}, {"id": "a", "text": "She continued her trip despite the storm warning."}]'::jsonb, 2, '{"strategy": "canceled because of = ביטלה בגלל. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הופך את סדר האירועים", "סותר לגמרי — הייתה אזהרת סערה", "נכון! אותה סיבה-תוצאה בדיוק", "סותר ''canceled her trip''"]}', 1.02, -1.0, 0.25, 2, 'ai', NULL, true),
('73f22d66-52b8-4703-8a1e-7eacc064be90', 'restatement', 'The restaurant became popular quickly thanks to positive online reviews.', NULL, '[{"id": "d", "text": "The restaurant became unpopular because of online reviews."}, {"id": "c", "text": "The restaurant''s popularity had nothing to do with reviews."}, {"id": "a", "text": "The restaurant received negative reviews despite being popular."}, {"id": "b", "text": "Positive online reviews helped the restaurant become popular quickly."}]'::jsonb, 3, '{"strategy": "became popular thanks to = הפכה פופולרית הודות ל-. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הפוך — ''unpopular'' סותר ''popular''", "סותר את הקשר הסיבתי המפורש במקור", "סותר ''positive online reviews''", "נכון! אותה סיבה-תוצאה בדיוק"]}', 1.0, -1.0, 0.25, 2, 'ai', NULL, true),
('eb3cff9b-65b6-45a1-ab23-de547eb54dbd', 'restatement', 'He was promoted after working at the company for five years.', NULL, '[{"id": "b", "text": "After five years at the company, he was promoted."}, {"id": "c", "text": "He was promoted before joining the company."}, {"id": "d", "text": "He left the company after five years without a promotion."}, {"id": "a", "text": "He was promoted within his first year."}]'::jsonb, 0, '{"strategy": "promoted after five years = קודם אחרי חמש שנים. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["נכון! אותה עובדה בדיוק", "סותר את סדר האירועים", "סותר ''was promoted''", "סותר ''five years''"]}', 1.27, -1.0, 0.25, 2, 'ai', NULL, true),
('f16f41d4-58a7-4f35-bd0f-098d8905fbca', 'restatement', 'The store extended its hours during the holiday shopping season.', NULL, '[{"id": "d", "text": "The store''s hours never change."}, {"id": "c", "text": "During the holiday shopping season, the store extended its hours."}, {"id": "b", "text": "The store reduced its hours during the holidays."}, {"id": "a", "text": "The store closed completely during the holidays."}]'::jsonb, 1, '{"strategy": "extended hours during = הרחיבה שעות במהלך. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["סותר ''extended its hours''", "נכון! אותה עובדה בדיוק", "הפוך — ''reduced'' סותר ''extended''", "סותר לגמרי — היא הרחיבה שעות, לא נסגרה"]}', 1.14, -1.0, 0.25, 2, 'ai', NULL, true),
('5d788ea5-6d69-40dc-be59-3ff0073f5830', 'restatement', 'Because the bridge was under construction, traffic was rerouted.', NULL, '[{"id": "d", "text": "The construction began after traffic was rerouted."}, {"id": "b", "text": "Traffic continued normally despite the construction."}, {"id": "c", "text": "Traffic was rerouted because the bridge was under construction."}, {"id": "a", "text": "The bridge was built because traffic was rerouted."}]'::jsonb, 2, '{"strategy": "because...rerouted = בגלל...הוסטה. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הופך את סדר האירועים", "סותר ''was rerouted''", "נכון! אותה סיבה-תוצאה בדיוק", "הופך סיבה ותוצאה"]}', 1.42, -1.0, 0.25, 2, 'ai', NULL, true),
('77f82058-218e-4e0d-9d66-c7273dcf33f8', 'restatement', 'The professor postponed the exam due to a scheduling conflict.', NULL, '[{"id": "a", "text": "The exam was moved earlier due to the conflict."}, {"id": "b", "text": "The professor held the exam despite the scheduling conflict."}, {"id": "d", "text": "There was no scheduling conflict at all."}, {"id": "c", "text": "The exam was postponed by the professor because of a scheduling conflict."}]'::jsonb, 3, '{"strategy": "postponed due to = דחה בגלל. פעיל לסביל + סיבה.", "correct_reason": "אותה עובדה וסיבה בדיוק, בקול סביל.", "options_analysis": ["הפוך — ''moved earlier'' סותר ''postponed''", "סותר ''postponed''", "סותר את המקור — היה ניגוד לו''ז", "נכון! אותה עובדה וסיבה בדיוק, בקול סביל"]}', 1.02, -1.0, 0.25, 2, 'ai', NULL, true),
('3317a43f-dfb8-42e2-bc44-bee868a7204d', 'restatement', 'The band''s popularity grew steadily after their song went viral online.', NULL, '[{"id": "c", "text": "After their song went viral online, the band''s popularity grew steadily."}, {"id": "a", "text": "The song went viral because the band was already popular."}, {"id": "b", "text": "The band''s popularity declined after their song went viral."}, {"id": "d", "text": "The band''s popularity had no connection to the internet."}]'::jsonb, 0, '{"strategy": "grew after went viral = גדלה אחרי שהתפרסמה. פרט זמן וסיבה.", "correct_reason": "אותה עובדה וסדר בדיוק.", "options_analysis": ["נכון! אותה עובדה וסדר בדיוק", "הופך סיבה ותוצאה", "הפוך — ''declined'' סותר ''grew''", "סותר את הקשר לרשת שמוזכר במקור"]}', 1.46, -1.0, 0.25, 2, 'ai', NULL, true),
('a7ebed55-1010-4660-8a4c-bcd5b832cfb6', 'restatement', 'The company reduced its prices to compete with newer rivals.', NULL, '[{"id": "b", "text": "The company increased its prices to compete with rivals."}, {"id": "c", "text": "To compete with newer rivals, the company reduced its prices."}, {"id": "a", "text": "The company''s prices had nothing to do with competition."}, {"id": "d", "text": "The company had no rivals to compete with."}]'::jsonb, 1, '{"strategy": "reduced prices to compete = הורידה מחירים כדי להתחרות. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["הפוך — ''increased'' סותר ''reduced''", "נכון! אותה מטרה בדיוק", "סותר את מטרת ההורדה שצוינה במפורש", "סותר ''newer rivals'' המוזכרים במקור"]}', 1.03, -1.0, 0.25, 2, 'ai', NULL, true),
('9cb0afea-d8c3-415f-a385-001211cf6cb3', 'restatement', 'The hikers turned back when the weather suddenly worsened.', NULL, '[{"id": "c", "text": "The hikers continued despite the worsening weather."}, {"id": "b", "text": "The weather improved, so the hikers continued."}, {"id": "a", "text": "When the weather suddenly worsened, the hikers turned back."}, {"id": "d", "text": "The hikers turned back before the weather changed."}]'::jsonb, 2, '{"strategy": "turned back when worsened = חזרו כשהחמיר. תנאי זמן.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''turned back'' — הם כן חזרו", "הפוך — ''improved'' סותר ''worsened''", "נכון! אותה משמעות בדיוק", "הופך את סדר האירועים"]}', 1.51, -1.0, 0.25, 2, 'ai', NULL, true),
('4c6ea079-cc6f-46d4-a285-1bc9871e28eb', 'restatement', 'The clinic added extra staff to handle the growing number of patients.', NULL, '[{"id": "d", "text": "The number of patients decreased at the clinic."}, {"id": "c", "text": "The clinic had no patients to handle."}, {"id": "b", "text": "The clinic reduced staff despite more patients."}, {"id": "a", "text": "To handle the growing number of patients, the clinic added extra staff."}]'::jsonb, 3, '{"strategy": "added staff to handle growing = הוסיפה צוות כדי לטפל בגידול. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["סותר ''growing number of patients''", "סותר לגמרי את קיום המטופלים", "הפוך — ''reduced'' סותר ''added''", "נכון! אותה מטרה בדיוק"]}', 1.32, -1.0, 0.25, 2, 'ai', NULL, true),
('54d36d41-363a-4354-b00e-5b780fb127dd', 'reading_comprehension', 'What is the passage mainly about?', '77750541-cbd8-4d74-a746-76e62e03b263', '[{"id": "a", "text": "Cities experimenting with car-free downtown zones"}, {"id": "c", "text": "The history of public transportation"}, {"id": "d", "text": "How to build a new parking garage"}, {"id": "b", "text": "Why all cars should be banned everywhere"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה עוסקת באזורים ללא רכב במרכזי ערים.", "correct_reason": "כל הפסקה סוקרת את מגמת אזורי הרחוב ללא מכוניות, יתרונותיה וחששות ממנה.", "options_analysis": ["נכון! אזורים ללא רכב במרכזי ערים = הנושא הכולל", "לא מוזכר בפסקה כלל", "לא מוזכרות הוראות בנייה בפסקה", "הפסקה לא טוענת עמדה קיצונית כזו"]}', 1.4, -1.0, 0.25, 2, 'ai', NULL, true),
('caac76c1-2c1b-4687-b396-ed848ea99a4c', 'reading_comprehension', 'According to the passage, what benefit do local businesses sometimes report in car-free zones?', '77750541-cbd8-4d74-a746-76e62e03b263', '[{"id": "a", "text": "Fewer customers overall"}, {"id": "c", "text": "Increased foot traffic"}, {"id": "d", "text": "Higher taxes"}, {"id": "b", "text": "Longer opening hours"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את היתרון העסקי המוזכר בפסקה.", "correct_reason": "הפסקה אומרת: ''Local businesses in car-free zones sometimes report increased foot traffic''.", "options_analysis": ["סותר את הפסקה — מדובר בתנועת רגל מוגברת", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.14, -1.0, 0.25, 2, 'ai', NULL, true),
('9ecb1518-a5aa-4abe-a0ec-9321e0546738', 'reading_comprehension', 'What concern do some business owners raise about car-free zones, according to the passage?', '77750541-cbd8-4d74-a746-76e62e03b263', '[{"id": "a", "text": "That public transportation is too expensive"}, {"id": "c", "text": "That pedestrians cause more pollution than cars"}, {"id": "d", "text": "That limiting car access could reduce sales"}, {"id": "b", "text": "That car-free zones are illegal"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את החשש שמעלים בעלי עסקים בפסקה.", "correct_reason": "הפסקה אומרת: ''some business owners worry that limiting car access could reduce sales''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה, וגם לא הגיוני", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה"]}', 1.03, -1.0, 0.25, 2, 'ai', NULL, true),
('b16b095f-cd54-4f17-b127-d661a99f250c', 'reading_comprehension', 'The word "pedestrians" in the passage most closely means:', '77750541-cbd8-4d74-a746-76e62e03b263', '[{"id": "a", "text": "bicycle riders only"}, {"id": "d", "text": "public buses"}, {"id": "b", "text": "people traveling by car"}, {"id": "c", "text": "people walking"}]'::jsonb, 3, '{"strategy": "אוצר מילים בהקשר — ''reserving them for pedestrians, cyclists, and public transportation''.", "correct_reason": "pedestrians = הולכי רגל.", "options_analysis": ["לא קשור — רוכבי אופניים הם קטגוריה נפרדת ברשימה", "לא קשור למשמעות המילה — זו קטגוריה נפרדת ברשימה", "הפוך — הפסקה מדברת על אזורים ללא רכב", "נכון! pedestrians = הולכי רגל"]}', 1.39, -1.0, 0.25, 2, 'ai', NULL, true),
('8c155b29-61ff-4437-b5da-b3c68494204c', 'reading_comprehension', 'How do city planners typically respond to concerns about reduced car access, according to the passage?', '77750541-cbd8-4d74-a746-76e62e03b263', '[{"id": "a", "text": "By adding parking areas outside the zone and improving public transportation"}, {"id": "b", "text": "By banning all businesses from the area"}, {"id": "c", "text": "By ignoring business owners completely"}, {"id": "d", "text": "By reopening the streets to all traffic"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הפתרון המוצע בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''adding convenient parking areas just outside the car-free zone and improving public transportation connections''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה, וסותר את מטרת האזור", "סותר את הפסקה — מתייחסים לחששות באופן ישיר", "סותר את כל הפסקה"]}', 1.19, -1.0, 0.25, 2, 'ai', NULL, true);